mapper.select:
SELECT s.forward_id AS forwardId, MAX(s.name) AS name, MAX(s.in_port) AS inPort, MAX(s.remote_addr) AS remoteAddr, MAX(s.tunnel_id) AS tunnelId, MAX(s.user_id) AS userId, SUM(s.flow) AS flow, MAX(s.total_flow) AS totalFlow FROM statistics_flow_forward s WHERE s.created_time >= #{startTime}
AND s.user_id = #{userId}
GROUP BY s.forward_id HAVING SUM(s.flow) > 0 ORDER BY SUM(s.flow) DESC LIMIT #{limit}
